BEGIN;CREATE TABLE IF NOT EXISTS conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,assignment_id uuid REFERENCES work_assignments(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS conversation_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender_identity_id uuid NOT NULL REFERENCES identities(id) ON DELETE CASCADE,body text NOT NULL CHECK(length(body) BETWEEN 1 AND 4000),created_at timestamptz NOT NULL DEFAULT now());ALTER TABLE conversations ENABLE ROW LEVEL SECURITY;ALTER TABLE conversations FORCE ROW LEVEL SECURITY;ALTER TABLE conversation_messages ENABLE ROW LEVEL SECURITY;ALTER TABLE conversation_messages FORCE ROW LEVEL SECURITY;CREATE POLICY conversations_tenant_isolation ON conversations USING(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);CREATE POLICY conversation_messages_tenant_isolation ON conversation_messages USING(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE,DELETE ON conversations,conversation_messages TO app_runtime;COMMIT;
